package com.bobbuy.service;

import com.bobbuy.api.response.*;
import com.bobbuy.model.*;
import com.bobbuy.repository.*;
import com.bobbuy.security.*;
import org.springframework.jdbc.core.JdbcTemplate;
import org.springframework.security.authentication.UsernamePasswordAuthenticationToken;
import org.springframework.security.core.authority.SimpleGrantedAuthority;
import org.springframework.security.core.context.SecurityContextHolder;
import org.springframework.stereotype.Service;
import org.springframework.transaction.annotation.Transactional;
import java.time.Instant;
import java.util.*;

/** Durable photo batches. Only server-verified onboarding decisions can cross the publication boundary. */
@Service
public class PhotoQuickPublishService {
 public record Batch(String id,String supplierId,String market,String state,long total,long processing,long published,long needsInformation,long failed,long excluded,List<Item> items){}
 public record Item(String id,String requestKey,String jobId,String state,String productId,String issueCode,long revision,String imageState,String candidateImageUrl,String sourcePage,String matchBasis){}
 private static final Set<String> LANGUAGES=Set.of("zh-CN","zh-TW","ja-JP","en-US");
 private final JdbcTemplate jdbc;private final SupplierRepository suppliers;private final UserRepository users;private final ProductRepository products;
 private final JdbcCostcoOnboardingJobRepository jobs;private final CostcoNumberOnboardingService onboarding;private final CostcoEvidencePersistence evidence;
 private final ManualProductCreationService creation;private final PublicProductBrowseService browse;
 public PhotoQuickPublishService(JdbcTemplate jdbc,SupplierRepository suppliers,UserRepository users,ProductRepository products,JdbcCostcoOnboardingJobRepository jobs,CostcoNumberOnboardingService onboarding,CostcoEvidencePersistence evidence,ManualProductCreationService creation,PublicProductBrowseService browse){this.jdbc=jdbc;this.suppliers=suppliers;this.users=users;this.products=products;this.jobs=jobs;this.onboarding=onboarding;this.evidence=evidence;this.creation=creation;this.browse=browse;}
 private long owner(){var value=MerchantScope.current();if(value==null)throw new ApiException(ErrorCode.FORBIDDEN,"error.auth.forbidden");return value;}
 private static void validKey(String value){if(value==null||!value.matches("[A-Za-z0-9._:-]{1,100}"))throw new ApiException(ErrorCode.INVALID_REQUEST,"quick_publish.invalid");}
 @Transactional public Batch create(String requestKey,String supplierId,String market){long owner=owner();validKey(requestKey);if(market==null||!market.matches("[A-Z]{2}"))throw new ApiException(ErrorCode.INVALID_REQUEST,"quick_publish.invalid");if(suppliers.findById(supplierId).filter(s->Long.valueOf(owner).equals(s.getMerchantId())).isEmpty())throw new ApiException(ErrorCode.RESOURCE_NOT_FOUND,"onboarding.supplier_not_found");String id=UUID.randomUUID().toString();jdbc.update("insert into bb_photo_publish_batch(id,merchant_id,supplier_id,market,request_key) values(cast(? as uuid),?,?,?,?) on conflict(merchant_id,request_key) do nothing",id,owner,supplierId,market,requestKey);String actual=jdbc.queryForObject("select cast(id as text) from bb_photo_publish_batch where merchant_id=? and request_key=?",String.class,owner,requestKey);return get(actual);}
 @Transactional(readOnly=true) public List<Batch> list(){long owner=owner();return jdbc.query("select cast(id as text) from bb_photo_publish_batch where merchant_id=? order by updated_at desc limit 50",(r,n)->r.getString(1),owner).stream().map(id->read(id,owner)).toList();}
 @Transactional public Batch add(String batchId,String requestKey,List<byte[]> photos){long owner=owner();validKey(requestKey);if(photos==null||photos.isEmpty()||photos.size()>2)throw new ApiException(ErrorCode.INVALID_REQUEST,"quick_publish.photos");var batchRow=jdbc.query("select supplier_id,market,state from bb_photo_publish_batch where id=cast(? as uuid) and merchant_id=? for update",(r,n)->new String[]{r.getString(1),r.getString(2),r.getString(3)},batchId,owner).stream().findFirst().orElseThrow(()->new ApiException(ErrorCode.RESOURCE_NOT_FOUND,"quick_publish.not_found"));if(!"OPEN".equals(batchRow[2]))throw new ApiException(ErrorCode.INVALID_STATUS,"quick_publish.closed");var existing=jdbc.query("select cast(id as text) from bb_photo_publish_item where batch_id=cast(? as uuid) and request_key=?",(r,n)->r.getString(1),batchId,requestKey);if(!existing.isEmpty())return get(batchId);
  String item=UUID.randomUUID().toString();String primary=evidence.putPrivatePhoto(owner,photos.get(0));var job=onboarding.enqueue(new CostcoNumberOnboardingService.Input(owner,batchRow[0],batchRow[1],item,null,primary));if(photos.size()==2){String packaging=evidence.putPrivatePhoto(owner,photos.get(1));job=jobs.attachPackagingPhoto(job,packaging);}jdbc.update("insert into bb_photo_publish_item(id,batch_id,merchant_id,request_key,onboarding_job_id) values(cast(? as uuid),cast(? as uuid),?,?,?)",item,batchId,owner,requestKey,job.id());return get(batchId);
 }
 @Transactional public Batch exclude(String batchId,String itemId,long revision){long owner=owner();int n=jdbc.update("update bb_photo_publish_item set excluded=true,state='EXCLUDED',revision=revision+1,updated_at=current_timestamp where id=cast(? as uuid) and batch_id=cast(? as uuid) and merchant_id=? and revision=? and state not in ('PUBLISHED','EXISTING')",itemId,batchId,owner,revision);if(n!=1)throw new ApiException(ErrorCode.INVALID_STATUS,"quick_publish.conflict");finish(batchId,owner);return get(batchId);}
 @Transactional public Batch supplement(String batchId,String itemId,long revision,byte[] photo){long owner=owner();String jobId=jdbc.query("select onboarding_job_id from bb_photo_publish_item where id=cast(? as uuid) and batch_id=cast(? as uuid) and merchant_id=? and revision=? and state in ('NEEDS_INFORMATION','FAILED') for update",(r,n)->r.getString(1),itemId,batchId,owner,revision).stream().findFirst().orElseThrow(()->new ApiException(ErrorCode.INVALID_STATUS,"quick_publish.conflict"));String hash=evidence.putPrivatePhoto(owner,photo);var job=jobs.findOwned(jobId,owner).orElseThrow();jobs.restartWithPackagingPhoto(job,hash);jdbc.update("update bb_photo_publish_item set state='PROCESSING',issue_code=null,revision=revision+1,updated_at=current_timestamp where id=cast(? as uuid)",itemId);return get(batchId);}
 @Transactional public Batch retryImage(String batchId,String itemId,long revision){long owner=owner();int n=jdbc.update("update bb_official_image_lookup g set state='RETRY',issue_code=null,lease_token=null,lease_until=null,updated_at=current_timestamp from bb_photo_publish_item i where g.item_id=i.id and i.id=cast(? as uuid) and i.batch_id=cast(? as uuid) and i.merchant_id=? and i.revision=? and g.state in ('NOT_FOUND','FAILED')",itemId,batchId,owner,revision);if(n!=1)throw new ApiException(ErrorCode.INVALID_STATUS,"quick_publish.conflict");return get(batchId);}
 @Transactional public Batch seal(String batchId){long owner=owner();int changed=jdbc.update("update bb_photo_publish_batch set state='SEALED',updated_at=current_timestamp where id=cast(? as uuid) and merchant_id=? and state='OPEN' and exists(select 1 from bb_photo_publish_item where batch_id=cast(? as uuid))",batchId,owner,batchId);if(changed==0&&jdbc.queryForObject("select count(*) from bb_photo_publish_batch where id=cast(? as uuid) and merchant_id=? and state in ('SEALED','PUBLISHED')",Long.class,batchId,owner)==0)throw new ApiException(ErrorCode.INVALID_STATUS,"quick_publish.empty");finish(batchId,owner);return get(batchId);}
 @Transactional(readOnly=true) public Batch get(String id){long owner=owner();return read(id,owner);}
 private Batch read(String id,long owner){var head=jdbc.query("select supplier_id,market,state from bb_photo_publish_batch where id=cast(? as uuid) and merchant_id=?",(r,n)->new String[]{r.getString(1),r.getString(2),r.getString(3)},id,owner).stream().findFirst().orElseThrow(()->new ApiException(ErrorCode.RESOURCE_NOT_FOUND,"quick_publish.not_found"));var rows=jdbc.query("select cast(i.id as text),i.request_key,i.onboarding_job_id,i.state,i.product_id,i.issue_code,i.revision,g.state,g.candidate_url,g.source_page,g.match_basis from bb_photo_publish_item i left join bb_official_image_lookup g on g.item_id=i.id where i.batch_id=cast(? as uuid) and i.merchant_id=? order by i.created_at,i.id",(r,n)->new Item(r.getString(1),r.getString(2),r.getString(3),r.getString(4),r.getString(5),r.getString(6),r.getLong(7),r.getString(8),r.getString(9),r.getString(10),r.getString(11)),id,owner);return new Batch(id,head[0],head[1],head[2],rows.size(),rows.stream().filter(x->Set.of("PROCESSING","VERIFYING").contains(x.state())).count(),rows.stream().filter(x->Set.of("PUBLISHED","EXISTING").contains(x.state())).count(),rows.stream().filter(x->"NEEDS_INFORMATION".equals(x.state())).count(),rows.stream().filter(x->"FAILED".equals(x.state())).count(),rows.stream().filter(x->"EXCLUDED".equals(x.state())).count(),rows);}
 @Transactional public Optional<String> claim(){return jdbc.query("with picked as (select id from bb_photo_publish_item where excluded=false and state in ('PROCESSING','VERIFYING') and updated_at<current_timestamp-interval '2 seconds' order by updated_at,id limit 1 for update skip locked) update bb_photo_publish_item i set state='VERIFYING',updated_at=current_timestamp from picked where i.id=picked.id returning cast(i.id as text)",(r,n)->r.getString(1)).stream().findFirst();}
 @Transactional public void process(String itemId){var row=jdbc.query("select merchant_id,onboarding_job_id,cast(batch_id as text) from bb_photo_publish_item where id=cast(? as uuid) and excluded=false",(r,n)->new Object[]{r.getLong(1),r.getString(2),r.getString(3)},itemId).stream().findFirst();if(row.isEmpty())return;long merchant=(Long)row.get()[0];var user=users.findById(merchant).filter(u->u.isEnabled()&&u.getRoles().contains(Role.AGENT));if(user.isEmpty()){mark(itemId,"FAILED",null,"error.auth.forbidden");return;}var prior=SecurityContextHolder.getContext();var context=SecurityContextHolder.createEmptyContext();context.setAuthentication(new UsernamePasswordAuthenticationToken(new BobbuyAuthenticatedUser(user.get().getId(),user.get().getUsername(),user.get().getName(),user.get().getRoles()),null,List.of(new SimpleGrantedAuthority("ROLE_AGENT"))));SecurityContextHolder.setContext(context);try{publish(itemId,merchant,(String)row.get()[1],(String)row.get()[2]);}finally{SecurityContextHolder.setContext(prior);}}
 @Transactional protected void publish(String itemId,long merchant,String jobId,String batchId){if(jdbc.queryForObject("select count(*) from bb_photo_publish_item where id=cast(? as uuid) and merchant_id=? and excluded=false",Long.class,itemId,merchant)!=1)return;var job=jobs.findOwned(jobId,merchant).orElseThrow();if(Set.of(CostcoOnboardingJob.State.QUEUED,CostcoOnboardingJob.State.AI_INTAKE,CostcoOnboardingJob.State.EVIDENCE_FETCH,CostcoOnboardingJob.State.AI_REVIEW,CostcoOnboardingJob.State.RETRY_WAIT).contains(job.state())){mark(itemId,"PROCESSING",null,null);return;}var candidate=job.decisions().stream().filter(d->d.stage()==CostcoOnboardingDecision.Stage.ADMISSION&&d.verdict()==CostcoOnboardingDecision.Verdict.ACCEPT&&d.trace()!=null&&d.candidate()!=null).reduce((a,b)->b).map(CostcoOnboardingDecision::candidate).orElse(null);if(candidate==null){mark(itemId,job.state()==CostcoOnboardingJob.State.FAILED?"FAILED":"NEEDS_INFORMATION",null,Objects.requireNonNullElse(job.failureCode(),"quick_publish.unverified"));return;}String issue=validate(candidate);if(issue!=null){mark(itemId,"NEEDS_INFORMATION",null,issue);return;}String createdProductId=jdbc.queryForObject("select product_id from bb_photo_publish_item where id=cast(? as uuid)",String.class,itemId);var matches=products.findAllByMerchantIdAndItemNumber(merchant,candidate.itemNumber());if(products.deletedCodeCount(merchant,candidate.itemNumber())>0||matches.size()>1){mark(itemId,"NEEDS_INFORMATION",null,"quick_publish.identity_conflict");return;}Product product;if(matches.size()==1){product=matches.get(0);var data=product.getCatalogData();boolean exact=(product.getId().equals(createdProductId)||candidate.target()!=null&&product.getId().equals(candidate.target().productId()))&&data!=null&&Objects.equals(job.supplierId(),data.supplierId())&&Objects.equals(candidate.packaging(),data.packaging())&&Objects.equals(candidate.translatedSpecifications(),data.specification());if(!exact){mark(itemId,"NEEDS_INFORMATION",null,"quick_publish.identity_conflict");return;}if(product.getVisibilityStatus()==ProductVisibility.PUBLIC){verifyAndMark(itemId,batchId,product,"EXISTING");return;}mark(itemId,"NEEDS_INFORMATION",null,"quick_publish.private_existing");return;}var details=candidate.archiveDetails();var input=new ManualProductCreationService.Input(UUID.fromString(itemId),candidate.translatedNames(),candidate.translatedDescriptions(),candidate.translatedSpecifications(),candidate.itemNumber(),candidate.brand(),details.categoryNodeId(),null,Map.of("quickPublishBatch",batchId),Map.of(),List.of(),details.storageCondition(),OrderMethod.PRE_ORDER,List.of());product=creation.createPhoto(input,job.supplierId(),job.market());product.setCatalogData(new ProductCatalogData(candidate.translatedSpecifications(),candidate.model(),candidate.packaging(),List.of(details.categoryNodeId()),job.supplierId(),null,merchant,Instant.now()));product.setVisibilityStatus(ProductVisibility.PUBLIC);products.saveAndFlush(product);var data=product.getCatalogData();product.setCatalogData(new ProductCatalogData(data.specification(),data.model(),data.packaging(),data.categoryIds(),data.supplierId(),ProductCatalogService.sourceHash(product),merchant,data.reviewedAt()));products.saveAndFlush(product);verifyAndMark(itemId,batchId,product,"PUBLISHED");}
 private String validate(CostcoOnboardingDecision.Candidate c){if(c.itemNumber()==null||c.itemNumber().isBlank()||c.name()==null||c.name().isBlank()||c.packaging()==null||c.packaging().isBlank()||c.archiveDetails()==null||c.archiveDetails().categoryNodeId()==null||c.translatedNames()==null||!complete(c.translatedNames())||!complete(c.translatedSpecifications())||!complete(c.translatedDescriptions()))return "quick_publish.missing_facts";if(c.unknownFields().stream().anyMatch(v->Set.of("itemNumber","name","specification","packaging","category","description","identity","translation").contains(v)))return "quick_publish.missing_facts";return null;}
 private boolean complete(Map<String,String> values){return values!=null&&values.keySet().containsAll(LANGUAGES)&&LANGUAGES.stream().allMatch(k->values.get(k)!=null&&!values.get(k).isBlank());}
 private void verifyAndMark(String item,String batch,Product p,String state){try{var detail=browse.detail(p.getId(),p.getMerchantId());if(!detail.item().productId().equals(p.getId()))throw new IllegalStateException();mark(item,state,p.getId(),null);finish(batch,p.getMerchantId());}catch(RuntimeException failed){mark(item,"VERIFYING",p.getId(),"quick_publish.readback_pending");}}
 private void mark(String id,String state,String product,String issue){jdbc.update("update bb_photo_publish_item set state=?,product_id=coalesce(?,product_id),issue_code=?,revision=revision+1,updated_at=current_timestamp where id=cast(? as uuid)",state,product,issue,id);}
 private void finish(String batch,long owner){String state=jdbc.queryForObject("select state from bb_photo_publish_batch where id=cast(? as uuid) and merchant_id=?",String.class,batch,owner);if(!"SEALED".equals(state))return;Long remaining=jdbc.queryForObject("select count(*) from bb_photo_publish_item where batch_id=cast(? as uuid) and merchant_id=? and excluded=false and state not in ('PUBLISHED','EXISTING')",Long.class,batch,owner);Long total=jdbc.queryForObject("select count(*) from bb_photo_publish_item where batch_id=cast(? as uuid) and merchant_id=? and excluded=false",Long.class,batch,owner);if(total!=null&&total>0&&remaining!=null&&remaining==0){jdbc.update("update bb_photo_publish_batch set state='PUBLISHED',updated_at=current_timestamp where id=cast(? as uuid) and merchant_id=? and state='SEALED'",batch,owner);jdbc.update("insert into bb_official_image_lookup(id,batch_id,item_id,merchant_id,product_id) select gen_random_uuid(),batch_id,id,merchant_id,product_id from bb_photo_publish_item where batch_id=cast(? as uuid) and merchant_id=? and excluded=false and state in ('PUBLISHED','EXISTING') on conflict(item_id) do nothing",batch,owner);}}
}
